class Colors(object):
    """
    Colors for bash terminal
    """
    HEADER = '\033[95m'
    OKBLUE = '\033[94m'
    OKGREEN = '\033[92m'
    WARNING = '\033[93m'
    FAIL = '\033[91m'
    ENDC = '\033[0m'
    BOLD = '\033[1m'
    UNDERLINE = '\033[4m'


def format_console_output(text, color=None):
    """

    :param text:
    :param color:
    :return:
    """
    if color == 'green':
        return '{}{}{}'.format(Colors.OKGREEN, text, Colors.ENDC)
    elif color == 'info':
        return '{}{}{}'.format(Colors.OKBLUE, text, Colors.ENDC)
    elif color == 'warning':
        return '{}{}{}'.format(Colors.WARNING, text, Colors.ENDC)
    elif color == 'error':
        return '{}{}{}'.format(Colors.FAIL, text, Colors.ENDC)
    else:
        return text
